        body: `■ 底面を 1cm ずつ積み上げる
角柱は、底面と同じ形の板を高さのぶんだけ積み上げた立体です。底面積が 12cm² なら、高さ 1cm の板の体積は 12cm³（1cm³ の立方体が 12 個）。それを 10cm 積めば 12×10 ＝ **120cm³**。1 円玉を積むと高さのぶんだけかさが増えるのと同じで、**底面積 × 高さ ＝ 「1cm ぶんの板」× 枚数**です。底面が三角形でも五角形でも円でも、この考え方は変わりません。

■ 240cm³ がまちがいである理由
ひっかけの 240cm³ は 6×4×10 で、底面の三角形の面積に ÷ 2 をしていません。6×4 は「底辺 6・高さ 4 の長方形」の面積で、三角形はその半分。三角柱は同じ底面の直方体（240cm³）を対角線で切った半分なので 120cm³。**底面が三角形なら ÷ 2**——平面の三角形の面積と同じ注意です。

■ 横に倒しても体積は変わらない
直角をはさむ 2 辺が 3cm・4cm の三角形を底面とし、柱の長さ 10cm の三角柱を横に倒して置いても、体積は 3×4÷2×10 ＝ **60cm³** のまま。ひっかけの 120cm³ は、倒したときに「高さ」を取りちがえた（10 ではなく別の長さを使った）か、底面を 6×4 の三角形と混同したものです。体積は置き方によらず、**「底面（合同な 2 つの面）」と「その間のきょり（柱の長さ）」**で決まります。倒して置くと、三角形の面が横を向いていても、それが底面です。

■ 底面の見つけ方
角柱の底面は「合同で平行な 2 つの面」。三角柱なら三角形の面 2 つ、置き方が変わっても三角形の面が底面です。高さは 2 つの底面の間のきょり（柱の長さ）で、底面の三角形の高さ（4cm）とはちがいます。**「底面の高さ」と「柱の高さ」の 2 つの「高さ」を区別**します。

■ 手順
①合同で平行な 2 つの面（底面）を見つける ②底面積を出す（三角形なら ÷ 2）③底面の間のきょり（柱の長さ）をかける ④単位 cm³。

★ ここがポイント：角柱は底面の板を高さのぶん積み上げた立体なので、体積 ＝ **底面積 × 高さ**。底面が三角形なら **÷ 2**。置き方を変えても体積は同じで、底面は「合同で平行な 2 つの面」、高さはその間のきょり（底面の三角形の高さとは別）。`,
