        heading: 'なぜ「中点」なら三角すいの辺は 1 辺の半分になるのか',
        figureId: 'sext06_s219_naze',
        body: `■ 切り落とされる三角すいの辺は「頂点から切断点まで」
頂点を切り落とす三角すいの 3 辺は、立方体の頂点から各切断点までの長さです。切断点が辺の中点なら、頂点から中点までは 1 辺の半分：12÷2 ＝ **6cm**。3 辺が 6cm・6cm・6cm の直角三角すいなので、底面 6×6÷2 ＝ 18cm²、高さ 6cm、体積 18×6÷3 ＝ **36cm³**。

■ 72cm³ がまちがいである理由
ひっかけの 72cm³ は、3 辺のうち 1 つに立方体の 1 辺 12cm をそのまま使った（18×12÷3）ものです。「中点」と書いてあるのに 12 を使うと、頂点から中点までの長さではなく辺全体の長さになり、三角すいが 2 倍の高さになります。**「中点」の字を見たら 2 でわる**——3 辺すべてです。

■ 立方体の 1/48 になる理由
三角すい 36cm³、立方体 12×12×12 ＝ 1,728cm³。1,728÷36 ＝ 48 なので **1/48**。1 辺 6 の小さい立方体（216）の 1/6 が三角すい（36）で、小さい立方体は大きい立方体の 1/8（1 辺が半分 → 体積は 2×2×2 ＝ 8 分の 1）。1/6 × 1/8 ＝ 1/48。ひっかけの 1/8 は小さい立方体の割合で、三角すいの割合ではありません。**「1 辺が半分の立方体」（1/8）と「その立方体の頂点を切った三角すい」（さらに 1/6）は別**です。

■ 3 辺の長さがちがう場合
切断点が 3 辺で異なる位置（たとえば 6cm・4cm・3cm）でも、直角三角すいの体積は 3 辺の積 ÷ 6：6×4×3÷6 ＝ 12cm³。底面（直角三角形）× 高さ ÷ 3 ＝ (6×4÷2)×3÷3 ＝ 12 で同じ。**直角三角すい ＝ 3 辺の積 ÷ 6** と覚えると速い。

■ 手順
①切断点が頂点から何 cm か（中点なら 1 辺 ÷ 2）を 3 辺とも書く ②直角三角すいの体積 ＝ 3 辺の積 ÷ 6（または 底面 × 高さ ÷ 3）③立方体との比は 立方体 ÷ 三角すい。

★ ここがポイント：三角すいの辺は**頂点から切断点まで**なので、中点なら **1 辺 ÷ 2**（3 辺とも）。直角三角すいの体積 ＝ **3 辺の積 ÷ 6**。立方体との比は 1/8（小さい立方体）× 1/6 ＝ 1/48。`,
