        body: `■ おもりが押しのけた水が、上に積み上がる
おもりを完全に沈めると、おもりがあった場所の水は、おもりの体積とちょうど同じ量だけ押しのけられ、水面の上に積み上がります。積み上がる水は底面積 40cm² の板の形なので、その高さは 300÷40 ＝ **7.5cm**。新しい深さは 15＋7.5 ＝ 22.5cm。おもりの形が複雑でも、**押しのける量 ＝ おもりの体積**なので、水位の上昇からおもりの体積が逆算できます（アルキメデスの発見と同じ考え）。

■ 315cm がまちがいである理由
ひっかけの 315cm は 15＋300 で、体積（cm³）をそのまま深さ（cm）に足したものです。体積を深さに直すには底面積でわる必要があります。**単位がちがうものは足せない**——cm³ を cm にしてから足します。

■ あふれるときは容器の高さで止まる
底面積 40cm²・高さ 20cm の容器に深さ 18cm まで水があり、200cm³ のおもりを沈めると、計算上の水位は 18＋200÷40 ＝ 23cm。でも容器の高さは 20cm なので、3cm ぶん（120cm³）の水はあふれ、水面は **20cm**（容器のふち）で止まります。ひっかけの 23cm は容器の高さを見ていません。**計算した水位が容器の高さをこえたら、答えは容器の高さ**。あふれた量 ＝ (計算した水位 − 容器の高さ) × 底面積 も、よく問われます。

■ おもりが水面から出るとき
おもりが完全に沈まず一部が水面から出る場合は、押しのけるのは水に沈んだ部分だけ。「完全に沈める」と書いてあるかを確かめてから、おもり全体の体積を使います。

■ 手順
①おもりの体積 ÷ 底面積 ＝ 上がる深さ ②もとの深さに足す ③容器の高さと比べ、こえていれば容器の高さが答え（あふれた量 ＝ こえた分 × 底面積）④「完全に沈める」か確かめる。

★ ここがポイント：沈めたおもりは**体積ぶんの水を押しのけ**、それが底面積の板として積み上がるので、水位の上昇 ＝ **おもりの体積 ÷ 底面積**（体積をそのまま深さに足さない）。計算した水位が**容器の高さをこえたら答えは容器の高さ**（残りはあふれる）。`,
