        figureId: 'sext06_s233_naze',
        body: `■ 体積は「くりぬいた分」を引くだけ
1 辺 9cm の立方体に 3×3 の正方形の穴を反対側までまっすぐ貫通させると、取りのぞかれるのは 3×3×9 ＝ 81cm³ の四角柱。体積 ＝ 729−81 ＝ **648cm³**。ひっかけの 702cm³ は 729−27 で、穴を 1 辺 3 の立方体（27）と見たものです。貫通しているので穴の長さは立方体の 1 辺 9cm いっぱいで、3×3×9 の柱です。

■ 表面積は 2 つの変化が起こる
穴をあけると、①穴の入口と出口の正方形（3×3 が 2 枚 ＝ 18cm²）は無くなる ②かわりに穴の内側（トンネルの壁）に新しい面ができる。トンネルの壁は 3×9 の長方形が 4 枚（上下左右）で 108cm²。表面積 ＝ 486−18＋108 ＝ **576cm²**。ひっかけの 468cm² は①だけを引いて②を足していません。**穴をあけると表面積はむしろ増える**（108 ＞ 18）ことが多い——手で触れる面が増えるからです。

■ 新しい面の数え方
トンネルの壁は、穴の断面のまわりの長さ（3×4 ＝ 12cm）× 穴の長さ（9cm）＝ 108cm²。円柱の側面積を「円周 × 高さ」で出したのと同じ考え方で、**穴の側面積 ＝ 断面のまわりの長さ × 穴の長さ**。断面が円の穴なら 円周 × 長さ。

■ 貫通しない穴（くぼみ）のとき
穴が途中で止まる（貫通しない）場合は、入口 1 枚だけが無くなり、壁 4 枚と底 1 枚が増えます。**貫通か、くぼみか**で、無くなる面（2 枚か 1 枚）と増える面（底があるか）がちがいます。

■ 手順
①体積：もと − くりぬいた柱（断面 × 長さ）②表面積：もと − 入口出口（貫通なら 2 枚）＋ 穴の壁（まわりの長さ × 長さ）（＋ 底、くぼみなら）③増える面 ＞ 減る面 になることが多いと知っておく。

★ ここがポイント：貫通した穴の体積は**もと − 断面 × 長さ**（穴は柱、長さは 1 辺いっぱい）。表面積は**入口出口の 2 枚が減り、穴の壁（まわりの長さ × 長さ）が増える**ので、減る分だけ引かない。貫通かくぼみかで枚数がちがう。`,
