        body: `■ 立体は同じ積み木の集まり
積み木で作った立体は、同じ大きさの立方体が集まったものです。だから体積 ＝ 1 個の体積 × 個数。個数は真上から見た図の段数を全部足して 19 個（前の単元）。1 辺 1cm なら 1 個 1cm³ で **19cm³**、1 辺 2cm なら 1 個 2×2×2 ＝ 8cm³ で 19×8 ＝ **152cm³**。

■ 10cm³ がまちがいである理由
ひっかけの 10cm³ は、正面から見える段数の合計（各列の最大値 3＋4＋3）を個数にしたものです。見えるのは各列のいちばん高い柱だけで、後ろに隠れた積み木は見えません。**個数は真上の図の段数をすべて足す**（投影図の単元と同じ）。

■ 38cm³ がまちがいである理由
1 辺 2cm の積み木で 38cm³ は 19×2 で、1 個の体積を 2cm³ としたものです。1 辺 2cm の立方体は 2×2×2 ＝ 8cm³。**1 辺を 2 倍にすると体積は 8 倍**（相似比の 3 乗）。19 個なら 152cm³。

■ 3 方向の図から個数を決める
正面図・側面図だけでは個数が 1 つに決まらない（隠れた積み木の有無で変わる）ので、「最大で何個・最小で何個」を問う問題になります。最大は、正面と側面の両方の高さを満たす範囲で各マスをできるだけ高く積んだ数、最小は、必要な高さの柱だけを残した数。真上の図に段数が書いてあれば 1 つに決まります。

■ 表面積は個数からは出ない
積み木の立体の表面積は、くっついた面が隠れるので「1 個の表面積 × 個数」にはなりません。6 方向から見える面を数える（上下・前後・左右から見える正方形の数）方法で求めます。**体積は個数から、表面積は見える面から**。

■ 手順
①真上の図の段数を全部足して個数 ②1 個の体積（1 辺 × 1 辺 × 1 辺）③かける ④見える面の数と混同していないか確かめる。

★ ここがポイント：積み木の立体の体積 ＝ **1 個の体積 × 個数**。個数は**真上の図の段数の合計**（見える面の数ではない）。1 辺 2cm なら 1 個 8cm³（1 辺 2 倍で体積 8 倍）。表面積は個数からは出ず、見える面を数える。`,
