        body: `■ 街灯の光は 1 点から広がる
街灯の光は電球の 1 点から出て四方に広がります。人の頭のてっぺんを通り過ぎた光がそのまま地面に届いた点が影の先端。だから**街灯（光源）・人の頭・影の先端は一直線**に並びます。この直線と地面と、街灯・人の 2 本の垂線で、大小 2 つの直角三角形ができ、角が共通なので相似。太陽の光は平行なので「高さの比 ＝ 影の比」という単純な比例でしたが、街灯では光が広がるため、**影の長さは街灯からのきょりで変わります**。

■ 式の立て方
街灯の真下から影の先端までを L とすると、大きい三角形（街灯 4m・底辺 L）と小さい三角形（人 1.5m・底辺 L−8）が相似。4:L ＝ 1.5:(L−8)。外項の積 ＝ 内項の積 で 4(L−8) ＝ 1.5L → 4L−32 ＝ 1.5L → 2.5L ＝ 32 → L ＝ 12.8m。影の長さ ＝ L−8 ＝ **4.8m**。小学生の解き方では、大小の三角形の高さの比 4:1.5 ＝ 8:3 から底辺の比も 8:3、差 8−3 ＝ 5 が 8m にあたるので 1 あたり 1.6m、影（3 にあたる）＝ 4.8m。

■ 3m がまちがいである理由
ひっかけの 3m は、太陽の影の式「高さ:影 が同じ」を当てはめて、1.5:x ＝ 4:8 としたものです。街灯の影は光源からのきょりで決まり、街灯の真下から 8m 離れた人の影は 4.8m。同じ人でも街灯から遠ざかるほど影は長くなり（光が浅い角度になる）、太陽の影のように「どこでも同じ比」にはなりません。**光が平行か 1 点からかを最初に確かめる**。

■ 10m がまちがいである理由
街灯 3m・人 1.2m・6m 離れた問題で 10m は、L（真下から影の先端まで）そのものです。影の長さは人の位置から先端までなので L−6 ＝ **4m**。**「影の長さ」は人の足もとから測る**——L は街灯の真下からの長さで、そこから人までの 6m を引きます。

■ 手順
①光源が点（街灯）か平行（太陽）かを確かめる ②点なら、光源・頭・影の先端が一直線 → 大小の直角三角形の相似 ③高さの比 ＝ 底辺の比 で、底辺の差（人の位置）から 1 あたりを出す ④影の長さ ＝ 人から先端まで（真下からの長さから人までを引く）。

★ ここがポイント：街灯の光は 1 点から広がるので、**光源・頭・影の先端が一直線**になり、大小の直角三角形が**相似**。高さの比 ＝ 底辺の比（差が人の位置）。太陽の「高さ:影 が同じ」は使えない。影の長さは**人の足もとから先端まで**（真下からの L から人までを引く）。`,
